using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class CaptureReverseDetails {public static string Main(){EditorApplication.delayCall+=()=>{try{EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var go=new GameObject("Temporary detail camera");var c=go.AddComponent<Camera>();c.CopyFrom(Camera.main);c.enabled=false;c.nearClipPlane=.1f;c.farClipPlane=1200;c.fieldOfView=60;
void Shot(string name,Vector3 eye,Vector3 target){c.transform.SetPositionAndRotation(eye,Quaternion.LookRotation(target-eye));var rt=new RenderTexture(1280,720,24);var old=RenderTexture.active;c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1280,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes("Docs/BackyardReverse/"+name+".png",t.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);}
Shot("pool-support",new(438,43,-212),new(410,34,-195));Shot("roger-house",new(464,91,-104),new(440,88,-82));Shot("pool-house-flight",new(379,109,33),new(407,82,0));Shot("dump-bypass",new(300,106,-47),new(287,74,-20));UnityEngine.Object.DestroyImmediate(go);File.WriteAllText("Docs/BackyardReverse/detail-capture-done.txt","Saved geometry detail views");}catch(Exception e){File.WriteAllText("Docs/BackyardReverse/detail-capture-error.txt",e.ToString());}};return "Capture scoped actual world and Reverse detail views";}}
